using System;\nusing NUnit.Framework;\nusing RestSharp;\nusing TechTalk.SpecFlow;\nusing AutomationFramework.API.BusinessLogic;\nusing AutomationFramework.Core.Utilities;\nusing Serilog;\nusing Newtonsoft.Json;\n\nnamespace AutomationFramework.API.StepDefinitions\n{\n    [Binding]\n    public class PetStoreSteps\n    {\n        private readonly ScenarioContext _scenarioContext;\n        private readonly PetStoreApiHelper _petStoreApiHelper;\n        private RestResponse _response;\n\n        public PetStoreSteps(ScenarioContext scenarioContext)\n        {\n            _scenarioContext = scenarioContext;\n            _petStoreApiHelper = new PetStoreApiHelper();\n        }\n\n        [Given(@\"the API endpoint is \"(.*)\"\")]\n        public void GivenTheApiEndpointIs(string endpoint)\n        {\n            _scenarioContext[\"endpoint\"] = endpoint;\n        }\n\n        [Given(@\"the pet ID is (.*)\")]\n        public void GivenThePetIdIs(int petId)\n        {\n            _scenarioContext[\"petId\"] = petId;\n        }\n\n        [When(@\"I send a POST request with the following data:\")]\n        public void WhenISendAPostRequestWithTheFollowingData(Table table)\n        {\n            var petData = new\n            {\n                id = int.Parse(table.Rows[0][\"id\"]),\n                name = table.Rows[0][\"name\"],\n                status = table.Rows[0][\"status\"]\n            };\n            _response = _petStoreApiHelper.SendPostRequest((string)_scenarioContext[\"endpoint\"], petData);\n        }\n\n        [When(@\"I send a GET request\")]\n        public void WhenISendAGetRequest()\n        {\n            var endpoint = $\"{_scenarioContext[\"endpoint\"]}/{_scenarioContext[\"petId\"]}\";\n            _response = _petStoreApiHelper.SendGetRequest(endpoint);\n        }\n\n        [When(@\"I send a PUT request with the following data:\")]\n        public void WhenISendAPutRequestWithTheFollowingData(Table table)\n        {\n            var petData = new\n            {\n                id = int.Parse(table.Rows[0][\"id\"]),\n                name = table.Rows[0][\"name\"],\n                status = table.Rows[0][\"status\"]\n            };\n            _response = _petStoreApiHelper.SendPutRequest((string)_scenarioContext[\"endpoint\"], petData);\n        }\n\n        [When(@\"I send a DELETE request\")]\n        public void WhenISendADeleteRequest